import os,subprocess,json,platform,re
p=Path(__file__).resolve().parent;r=Path('/tmp/xdiff/rustc.txt').read_text().strip();e=os.environ.copy();e['LD_LIBRARY_PATH']=Path('/tmp/xdiff/libdir.txt').read_text().strip()+':'+e.get('LD_LIBRARY_PATH','');cmd=[r,'--edition=2024','-O','-C','codegen-units=1','-C','llvm-args=-rotation-max-header-size=0','--emit=link,llvm-ir,asm',str(p/'probe.rs'),'-o',str(p/'norotate')];x=subprocess.run(cmd,env=e,capture_output=True,text=True);x.check_returncode();s=(p/'norotate.ll').read_text();f=re.search(r'^define[^\n]*@original\([^\n]*\).*?^}',s,re.M|re.S).group();y=subprocess.check_output([str(p/'norotate'),'check','1'],env=e,text=True);out={'command':cmd,'original_checked_muls':f.count('@llvm.smul.with.overflow'),'check':y,'stderr':x.stderr};(p/('rotation.'+platform.machine()+'.json')).write_text(json.dumps(out,indent=2));print(out)
